package com.harish.student_management.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="bus_locations") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class BusLocation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="trip_id",nullable=false) BusTrip trip; @Column(nullable=false) Double latitude; @Column(nullable=false) Double longitude; Double speed; @Column(name="recorded_at",nullable=false) LocalDateTime recordedAt; @Column(name="eta_minutes") Integer etaMinutes; }
